## Steps

### Step 1: Add `max_nesting_depth` to complexity.rs

Reuse the existing `classify_cognitive` classification to identify nesting-incrementing constructs. Walk the tree tracking max depth only — no scoring. Handles else-if chains the same way cognitive does (flat, no extra nesting).

```rust
// src/parser/complexity.rs

pub fn max_nesting_depth(node: Node, src: &[u8], lang: &str) -> u32 {
    let mut max_depth = 0;
    walk_nesting(node, src, lang, 0, &mut max_depth);
    max_depth
}

fn walk_nesting(node: Node, src: &[u8], lang: &str, current_depth: u32, max_depth: &mut u32) {
    let kind = node.kind();
    let (_, increments_nesting) = classify_cognitive(kind, lang);
    let new_depth = if increments_nesting { current_depth + 1 } else { current_depth };
    if new_depth > *max_depth {
        *max_depth = new_depth;
    }

    let mut cursor = node.walk();
    for child in node.children(&mut cursor) {
        // else-if chains: same logic as walk_cognitive — don't add nesting for chained if
        if lang == "rust" && child.kind() == "else_clause" {
            let mut inner_cursor = child.walk();
            for grandchild in child.children(&mut inner_cursor) {
                if grandchild.kind() == "if_expression" {
                    walk_nesting(grandchild, src, lang, current_depth, max_depth);
                } else {
                    walk_nesting(grandchild, src, lang, new_depth, max_depth);
                }
            }
            continue;
        }
        walk_nesting(child, src, lang, new_depth, max_depth);
    }
}
```

